import { gsap } from 'gsap';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, smoothstep, uniform, time, vec2, sub } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ============================================================================
  // PARSE CONFIG
  // ============================================================================
  const colors = config.intent?.visualSpec?.colors || {
    background: '#0b0b10',
    surface: '#111117',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
  };

  const textItems = [
    'CAL NA-01 BEAT 28800 VPH',
    'POWER RESERVE 72H',
    'CASE 40.5 MM 904L',
    'REF 5811 IN STOCK',
    'WAITLIST 1204',
    'NEXT FITTING JUL 18',
  ];

  const ribbonWidth = 7.0;
  const ribbonHeight = 0.35;
  const figureSize = 13;
  const tickMarkWidth = 0.02 * ribbonWidth;
  const tickMarkHeight = 0.14;
  const gap = 0.5;
  const fadeWidth = 0.6;
  const figureZ = 0.02;
  const scrollSpeed = 0.4;
  const tickAccent = '#ff2a38';
  const tickEmissive = 1.5;

  // ============================================================================
  // ROOT GROUP
  // ============================================================================
  const root = new THREE.Group();
  root.position.set(0, 0, 0);
  root.rotation.set(0, 0, 0);
  root.scale.set(1, 1, 1);

  // ============================================================================
  // RIBBON PLANE (backing surface)
  // ============================================================================
  const ribbonGeo = new THREE.PlaneGeometry(ribbonWidth, ribbonHeight);

  // Canvas-based texture for the ribbon backing + hairlines
  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 64;
  const ctx2d = canvas.getContext('2d');

  // Fill background
  ctx2d.fillStyle = colors.surface;
  ctx2d.fillRect(0, 0, canvas.width, canvas.height);

  // Top hairline
  ctx2d.strokeStyle = '#23232b';
  ctx2d.lineWidth = 1;
  ctx2d.beginPath();
  ctx2d.moveTo(0, 2);
  ctx2d.lineTo(canvas.width, 2);
  ctx2d.stroke();

  // Bottom hairline
  ctx2d.beginPath();
  ctx2d.moveTo(0, canvas.height - 2);
  ctx2d.lineTo(canvas.width, canvas.height - 2);
  ctx2d.stroke();

  const ribbonTexture = new THREE.CanvasTexture(canvas);
  ribbonTexture.magFilter = THREE.LinearFilter;
  ribbonTexture.minFilter = THREE.LinearFilter;

  const ribbonMat = new MeshBasicNodeMaterial();
  ribbonMat.map = ribbonTexture;
  ribbonMat.color.setHex(0x111117);

  const ribbonMesh = new THREE.Mesh(ribbonGeo, ribbonMat);
  ribbonMesh.position.z = -0.01;
  root.add(ribbonMesh);

  // ============================================================================
  // TEXT TICKER & SEPARATORS
  // ============================================================================
  const tickerGroup = new THREE.Group();
  root.add(tickerGroup);

  // Create text elements and separators
  const textObjects = [];
  let currentX = -ribbonWidth / 2 + 0.25;

  for (let i = 0; i < textItems.length; i++) {
    // Render text
    const textObj = ctx.fontAtlas.createText(textItems[i], {
      fontSize: figureSize,
      color: colors.paper,
      align: 'left',
    });
    textObj.position.z = figureZ;
    textObj.position.x = currentX;
    tickerGroup.add(textObj);
    textObjects.push(textObj);

    // Measure approximate width (mono, estimate ~0.08 units per char at this size)
    const charWidth = 0.008;
    const textWidth = textItems[i].length * charWidth;
    currentX += textWidth + gap;

    // Add separator (vertical red tick + gaps)
    if (i < textItems.length - 1) {
      const tickGeo = new THREE.PlaneGeometry(tickMarkWidth, tickMarkHeight);
      const tickMat = new MeshBasicNodeMaterial({
        color: tickAccent,
        emissive: tickAccent,
        emissiveIntensity: tickEmissive,
      });
      const tickMesh = new THREE.Mesh(tickGeo, tickMat);
      tickMesh.position.z = figureZ;
      tickMesh.position.x = currentX;
      tickerGroup.add(tickMesh);

      currentX += tickMarkWidth + gap;
    }
  }

  // Calculate total strip length
  const stripLength = currentX - (-ribbonWidth / 2 + 0.25);

  // Duplicate strip for seamless loop
  const stripGeo = new THREE.Group();
  tickerGroup.add(stripGeo);

  // Clone all children to stripGeo for animation
  const animatedStrip = new THREE.Group();
  tickerGroup.children.forEach(child => {
    const clone = child.clone();
    animatedStrip.add(clone);
  });
  tickerGroup.remove(animatedStrip);
  tickerGroup.add(animatedStrip);

  // Calculate loop period
  const loopPeriod = stripLength / scrollSpeed;

  // ============================================================================
  // FLY-THROUGH PRIMITIVE (horizontal scroll)
  // ============================================================================
  let flyResult = null;
  if (config.cinematicPrimitives) {
    const flyPrim = config.cinematicPrimitives.find(p => p.name === 'fly-through');
    if (flyPrim) {
      flyResult = ctx.primitives['fly-through'](animatedStrip, {
        speed: scrollSpeed,
        depthUnits: 0,
      });
    }
  }

  // If no primitive, manually set up the scroll animation
  if (!flyResult) {
    const scrollTimeline = gsap.timeline({ repeat: -1 });
    scrollTimeline.to(animatedStrip.position, {
      x: -stripLength,
      duration: loopPeriod,
      ease: 'none',
    }, 0);
  }

  // ============================================================================
  // EDGE FADE MASKS (via shader with gradient)
  // ============================================================================
  // Create a fade gradient texture for left/right edges
  const fadeCanvas = document.createElement('canvas');
  fadeCanvas.width = 512;
  fadeCanvas.height = 64;
  const fadectx = fadeCanvas.getContext('2d');

  // Create horizontal gradient: fade in on left, fade out on right
  const fadeGrad = fadectx.createLinearGradient(0, 0, fadeCanvas.width, 0);
  fadeGrad.addColorStop(0, 'rgba(11, 11, 16, 1)');
  fadeGrad.addColorStop(0.15, 'rgba(11, 11, 16, 0)');
  fadeGrad.addColorStop(0.85, 'rgba(11, 11, 16, 0)');
  fadeGrad.addColorStop(1, 'rgba(11, 11, 16, 1)');
  fadectx.fillStyle = fadeGrad;
  fadectx.fillRect(0, 0, fadeCanvas.width, fadeCanvas.height);

  const fadeTexture = new THREE.CanvasTexture(fadeCanvas);
  fadeTexture.magFilter = THREE.LinearFilter;
  fadeTexture.minFilter = THREE.LinearFilter;

  // Apply fade as an overlay plane above the ticker
  const fadeGeo = new THREE.PlaneGeometry(ribbonWidth, ribbonHeight);
  const fadeMat = new MeshBasicNodeMaterial();
  fadeMat.map = fadeTexture;
  fadeMat.transparent = true;
  fadeMat.blending = THREE.MultiplyBlending;

  const fadeMesh = new THREE.Mesh(fadeGeo, fadeMat);
  fadeMesh.position.z = 0.05;
  root.add(fadeMesh);

  // ============================================================================
  // CLEANUP
  // ============================================================================
  root.userData.cleanup = () => {
    if (flyResult && flyResult.cleanup) {
      flyResult.cleanup();
    }
    gsap.killTweensOf(animatedStrip.position);
    ribbonTexture.dispose();
    fadeTexture.dispose();
    ribbonMat.dispose();
    fadeMat.dispose();
    ribbonGeo.dispose();
    fadeGeo.dispose();
  };

  root.userData.handlers = {};

  return root;
}
